  1→import { i18n } from "@mariozechner/mini-lit";
  2→import { Dialog, DialogContent, DialogHeader } from "@mariozechner/mini-lit/dist/Dialog.js";
  3→import { Input } from "@mariozechner/mini-lit/dist/Input.js";
  4→import { Label } from "@mariozechner/mini-lit/dist/Label.js";
  5→import { Switch } from "@mariozechner/mini-lit/dist/Switch.js";
  6→import { getProviders } from "@mariozechner/pi-ai";
  7→import { html, LitElement, type TemplateResult } from "lit";
  8→import { customElement, property, state } from "lit/decorators.js";
  9→import "../components/ProviderKeyInput.js";
 10→import { getAppStorage } from "../storage/app-storage.js";
 11→
 12→// Base class for settings tabs
 13→export abstract class SettingsTab extends LitElement {
 14→	abstract getTabName(): string;
 15→
 16→	protected createRenderRoot() {
 17→		return this;
 18→	}
 19→}
 20→
 21→// API Keys Tab
 22→@customElement("api-keys-tab")
 23→export class ApiKeysTab extends SettingsTab {
 24→	getTabName(): string {
 25→		return i18n("API Keys");
 26→	}
 27→
 28→	render(): TemplateResult {
 29→		const providers = getProviders();
 30→
 31→		return html`
 32→			<div class="flex flex-col gap-6">
 33→				<p class="text-sm text-muted-foreground">
 34→					${i18n("Configure API keys for LLM providers. Keys are stored locally in your browser.")}
 35→				</p>
 36→				${providers.map((provider) => html`<provider-key-input .provider=${provider}></provider-key-input>`)}
 37→			</div>
 38→		`;
 39→	}
 40→}
 41→
 42→// Proxy Tab
 43→@customElement("proxy-tab")
 44→export class ProxyTab extends SettingsTab {
 45→	@state() private proxyEnabled = false;
 46→	@state() private proxyUrl = "http://localhost:3001";
 47→
 48→	override async connectedCallback() {
 49→		super.connectedCallback();
 50→		// Load proxy settings when tab is connected
 51→		try {
 52→			const storage = getAppStorage();
 53→			const enabled = await storage.settings.get<boolean>("proxy.enabled");
 54→			const url = await storage.settings.get<string>("proxy.url");
 55→
 56→			if (enabled !== null) this.proxyEnabled = enabled;
 57→			if (url !== null) this.proxyUrl = url;
 58→		} catch (error) {
 59→			console.error("Failed to load proxy settings:", error);
 60→		}
 61→	}
 62→
 63→	private async saveProxySettings() {
 64→		try {
 65→			const storage = getAppStorage();
 66→			await storage.settings.set("proxy.enabled", this.proxyEnabled);
 67→			await storage.settings.set("proxy.url", this.proxyUrl);
 68→		} catch (error) {
 69→			console.error("Failed to save proxy settings:", error);
 70→		}
 71→	}
 72→
 73→	getTabName(): string {
 74→		return i18n("Proxy");
 75→	}
 76→
 77→	render(): TemplateResult {
 78→		return html`
 79→			<div class="flex flex-col gap-4">
 80→				<p class="text-sm text-muted-foreground">
 81→					${i18n("Allows browser-based apps to bypass CORS restrictions when calling LLM providers. Required for Z-AI and Anthropic with OAuth token.")}
 82→				</p>
 83→
 84→				<div class="flex items-center justify-between">
 85→					<span class="text-sm font-medium text-foreground">${i18n("Use CORS Proxy")}</span>
 86→					${Switch({
 87→						checked: this.proxyEnabled,
 88→						onChange: (checked: boolean) => {
 89→							this.proxyEnabled = checked;
 90→							this.saveProxySettings();
 91→						},
 92→					})}
 93→				</div>
 94→
 95→				<div class="space-y-2">
 96→					${Label({ children: i18n("Proxy URL") })}
 97→					${Input({
 98→						type: "text",
 99→						value: this.proxyUrl,
100→						disabled: !this.proxyEnabled,
101→						onInput: (e) => {
102→							this.proxyUrl = (e.target as HTMLInputElement).value;
103→						},
104→						onChange: () => this.saveProxySettings(),
105→					})}
106→					<p class="text-xs text-muted-foreground">
107→						${i18n("Format: The proxy must accept requests as <proxy-url>/?url=<target-url>")}
108→					</p>
109→				</div>
110→			</div>
111→		`;
112→	}
113→}
