115→@customElement("settings-dialog")
116→export class SettingsDialog extends LitElement {
117→	@property({ type: Array, attribute: false }) tabs: SettingsTab[] = [];
118→	@state() private isOpen = false;
119→	@state() private activeTabIndex = 0;
120→
121→	protected createRenderRoot() {
122→		return this;
123→	}
124→
125→	static async open(tabs: SettingsTab[]) {
126→		const dialog = new SettingsDialog();
127→		dialog.tabs = tabs;
128→		dialog.isOpen = true;
129→		document.body.appendChild(dialog);
130→	}
131→
132→	private setActiveTab(index: number) {
133→		this.activeTabIndex = index;
134→	}
135→
136→	private renderSidebarItem(tab: SettingsTab, index: number): TemplateResult {
137→		const isActive = this.activeTabIndex === index;
138→		return html`
139→			<button
140→				class="w-full text-left px-4 py-3 rounded-md transition-colors ${
141→					isActive
142→						? "bg-secondary text-foreground font-medium"
143→						: "text-muted-foreground hover:bg-secondary/50 hover:text-foreground"
144→				}"
145→				@click=${() => this.setActiveTab(index)}
146→			>
147→				${tab.getTabName()}
148→			</button>
149→		`;
150→	}
151→
152→	private renderMobileTab(tab: SettingsTab, index: number): TemplateResult {
153→		const isActive = this.activeTabIndex === index;
154→		return html`
155→			<button
156→				class="px-3 py-2 text-sm font-medium transition-colors ${
157→					isActive ? "border-b-2 border-primary text-foreground" : "text-muted-foreground hover:text-foreground"
158→				}"
159→				@click=${() => this.setActiveTab(index)}
160→			>
161→				${tab.getTabName()}
162→			</button>
163→		`;
164→	}
165→
166→	render() {
167→		if (this.tabs.length === 0) {
168→			return html``;
169→		}
170→
171→		return Dialog({
172→			isOpen: this.isOpen,
173→			onClose: () => {
174→				this.isOpen = false;
175→				this.remove();
176→			},
177→			width: "min(1000px, 90vw)",
178→			height: "min(800px, 90vh)",
179→			backdropClassName: "bg-black/50 backdrop-blur-sm",
180→			children: html`
181→				${DialogContent({
182→					className: "h-full p-6",
183→					children: html`
184→						<div class="flex flex-col h-full overflow-hidden">
185→							<!-- Header -->
186→							<div class="pb-4 flex-shrink-0">${DialogHeader({ title: i18n("Settings") })}</div>
187→
188→							<!-- Mobile Tabs -->
189→							<div class="md:hidden flex flex-shrink-0 pb-4">
190→								${this.tabs.map((tab, index) => this.renderMobileTab(tab, index))}
191→							</div>
192→
193→							<!-- Layout -->
194→							<div class="flex flex-1 overflow-hidden">
195→								<!-- Sidebar (desktop only) -->
196→								<div class="hidden md:block w-64 flex-shrink-0 space-y-1">
197→									${this.tabs.map((tab, index) => this.renderSidebarItem(tab, index))}
198→								</div>
199→
200→								<!-- Content -->
201→								<div class="flex-1 overflow-y-auto md:pl-6">
202→									${this.tabs.map(
203→										(tab, index) =>
204→											html`<div style="display: ${this.activeTabIndex === index ? "block" : "none"}">${tab}</div>`,
205→									)}
206→								</div>
207→							</div>
208→						</div>
209→					`,
210→				})}
211→			`,
212→		});
213→	}
214→}
