  1→/**
  2→ * Provider Keys Settings Panel.
  3→ *
  4→ * Admin-only component for managing team API keys.
  5→ * Keys are stored server-side with envelope encryption.
  6→ */
  7→
  8→import { apiFetch } from "../shared/api.js";
  9→import { LitElement, html, css } from "lit";
 10→import { customElement, property, state } from "lit/decorators.js";
 11→
 12→interface ProviderKeyInfo {
 13→	provider: string;
 14→	hasKey: boolean;
 15→	config: Record<string, unknown>;
 16→	updatedAt: string;
 17→}
 18→
 19→const PROVIDER_LABELS: Record<string, string> = {
 20→	anthropic: "Anthropic",
 21→	openai: "OpenAI",
 22→	google: "Google (Gemini)",
 23→	groq: "Groq",
 24→	cerebras: "Cerebras",
 25→	xai: "xAI",
 26→	zai: "ZAI",
 27→	openrouter: "OpenRouter",
 28→	"vercel-ai-gateway": "Vercel AI Gateway",
 29→	mistral: "Mistral",
 30→	minimax: "MiniMax",
 31→	"minimax-cn": "MiniMax (CN)",
 32→	huggingface: "Hugging Face",
 33→	opencode: "OpenCode",
 34→	"kimi-coding": "Kimi Coding",
 35→	"azure-openai": "Azure OpenAI",
 36→};
 37→
 38→@customElement("provider-keys-panel")
 39→export class ProviderKeysPanel extends LitElement {
