 48→			gap: 0.5rem;
 49→			margin-bottom: 1rem;
 50→		}
 51→		.key-item {
 52→			display: flex;
 53→			align-items: center;
 54→			justify-content: space-between;
 55→			padding: 0.75rem 1rem;
 56→			border: 1px solid var(--border, #e5e7eb);
 57→			border-radius: 0.5rem;
 58→			background: var(--card, #fff);
 59→		}
 60→		.key-info {
