 68→		}
 69→		.key-date {
 70→			font-size: 0.75rem;
 71→			color: var(--muted-foreground, #6b7280);
 72→		}
 73→		.add-form {
 74→			display: flex;
 75→			flex-direction: column;
 76→			gap: 0.5rem;
 77→			padding: 1rem;
 78→			border: 1px solid var(--border, #e5e7eb);
