155→
156→	@property({ type: Function })
157→	getToken: (() => string | null) | undefined;
158→
159→	@state()
160→	private keys: ProviderKeyInfo[] = [];
161→
162→	@state()
163→	private loading = false;
164→
165→	@state()
166→	private saving = false;
167→
168→	@state()
169→	private statusMessage = "";
170→
171→	@state()
172→	private statusType: "success" | "error" = "success";
173→
174→	@state()
175→	private selectedProvider = "";
176→
177→	@state()
178→	private apiKeyInput = "";
179→
180→	@state()
181→	private azureBaseUrl = "";
182→
183→	@state()
184→	private azureApiVersion = "";
185→
186→	@state()
187→	private azureDeploymentNameMap = "";
188→
189→	override connectedCallback() {
190→		super.connectedCallback();
191→		this.loadKeys();
192→	}
193→
194→	private fetchApi = (url: string, options?: RequestInit) => apiFetch(url, options, this.getToken);
195→
196→	private async loadKeys() {
197→		this.loading = true;
198→		try {
199→			const result = await this.fetchApi("/api/provider-keys");
200→			if (result.success) {
201→				this.keys = result.data.keys;
202→			}
203→		} catch (err) {
204→			console.error("Failed to load provider keys:", err);
205→		} finally {
206→			this.loading = false;
207→		}
208→	}
209→
210→	private async handleAdd() {
211→		if (!this.selectedProvider || !this.apiKeyInput) return;
212→		if (this.selectedProvider === "azure-openai" && !this.azureBaseUrl) return;
213→
214→		this.saving = true;
215→		this.statusMessage = "";
216→		try {
217→			const body: Record<string, unknown> = {
218→				provider: this.selectedProvider,
219→				apiKey: this.apiKeyInput,
220→			};
221→
222→			if (this.selectedProvider === "azure-openai") {
223→				const config: Record<string, string> = { baseUrl: this.azureBaseUrl };
224→				if (this.azureApiVersion) config.apiVersion = this.azureApiVersion;
225→				if (this.azureDeploymentNameMap) config.deploymentNameMap = this.azureDeploymentNameMap;
226→				body.config = config;
227→			}
228→
229→			const result = await this.fetchApi("/api/provider-keys", {
230→				method: "POST",
231→				body: JSON.stringify(body),
232→			});
233→
234→			if (result.success) {
235→				this.statusMessage = `${PROVIDER_LABELS[this.selectedProvider] || this.selectedProvider} key saved.`;
236→				this.statusType = "success";
237→				this.apiKeyInput = "";
238→				this.selectedProvider = "";
239→				this.azureBaseUrl = "";
240→				this.azureApiVersion = "";
241→				this.azureDeploymentNameMap = "";
242→				await this.loadKeys();
243→			} else {
244→				this.statusMessage = result.error || "Failed to save key";
245→				this.statusType = "error";
246→			}
247→		} catch (err) {
248→			this.statusMessage = "Network error";
249→			this.statusType = "error";
250→		} finally {
251→			this.saving = false;
252→		}
253→	}
254→
255→	private async handleDelete(provider: string) {
256→		if (!confirm(`Remove the ${PROVIDER_LABELS[provider] || provider} API key?`)) return;
257→
258→		try {
259→			const result = await this.fetchApi(`/api/provider-keys/${provider}`, {
260→				method: "DELETE",
261→			});
262→
263→			if (result.success) {
264→				this.statusMessage = `${PROVIDER_LABELS[provider] || provider} key removed.`;
265→				this.statusType = "success";
266→				await this.loadKeys();
267→			} else {
268→				this.statusMessage = result.error || "Failed to remove key";
269→				this.statusType = "error";
270→			}
271→		} catch {
272→			this.statusMessage = "Network error";
273→			this.statusType = "error";
274→		}
275→	}
276→
277→	private get availableProviders(): string[] {
278→		const existing = new Set(this.keys.map((k) => k.provider));
279→		return Object.keys(PROVIDER_LABELS).filter((p) => !existing.has(p));
280→	}
281→
282→	override render() {
283→		return html`
284→			<h3>Provider API Keys</h3>
285→
286→			${this.statusMessage
287→				? html`<div class="status ${this.statusType === "success" ? "status-success" : "status-error"}">${this.statusMessage}</div>`
288→				: null}
289→
290→			${this.loading
291→				? html`<div class="empty">Loading...</div>`
292→				: this.keys.length === 0
293→					? html`<div class="empty">No API keys configured. Add one below.</div>`
294→					: html`
295→						<div class="key-list">
296→							${this.keys.map(
297→								(key) => html`
298→									<div class="key-item">
299→										<div class="key-info">
300→											<span class="key-provider">${PROVIDER_LABELS[key.provider] || key.provider}</span>
301→											${key.config?.baseUrl ? html`<span class="key-date">${key.config.baseUrl}</span>` : null}
302→											<span class="key-date">Updated ${new Date(key.updatedAt).toLocaleDateString()}</span>
303→										</div>
304→										<button class="btn-danger" @click=${() => this.handleDelete(key.provider)}>Remove</button>
305→									</div>
306→								`,
307→							)}
308→						</div>
309→					`}
310→
311→			<div class="add-form">
312→				<div class="form-row">
313→					<div class="form-field">
314→						<label>Provider</label>
315→						<select .value=${this.selectedProvider} @change=${(e: Event) => {
316→							this.selectedProvider = (e.target as HTMLSelectElement).value;
317→							this.azureBaseUrl = "";
318→							this.azureApiVersion = "";
319→							this.azureDeploymentNameMap = "";
320→						}}>
321→							<option value="">Select provider...</option>
322→							${this.availableProviders.map(
323→								(p) => html`<option value=${p}>${PROVIDER_LABELS[p] || p}</option>`,
324→							)}
325→						</select>
326→					</div>
327→					<div class="form-field">
328→						<label>API Key</label>
329→						<input
330→							type="password"
331→							placeholder="sk-..."
332→							.value=${this.apiKeyInput}
333→							@input=${(e: Event) => (this.apiKeyInput = (e.target as HTMLInputElement).value)}
334→						/>
335→					</div>
336→					<button
337→						class="btn-primary"
338→						?disabled=${!this.selectedProvider || !this.apiKeyInput || (this.selectedProvider === "azure-openai" && !this.azureBaseUrl) || this.saving}
339→						@click=${this.handleAdd}
340→					>
341→						${this.saving ? "Saving..." : "Add Key"}
342→					</button>
343→				</div>
344→				${this.selectedProvider === "azure-openai" ? html`
345→					<div class="form-row">
346→						<div class="form-field">
347→							<label>Endpoint URL *</label>
348→							<input
349→								type="url"
350→								placeholder="https://your-resource.openai.azure.com"
351→								.value=${this.azureBaseUrl}
352→								@input=${(e: Event) => (this.azureBaseUrl = (e.target as HTMLInputElement).value)}
353→							/>
354→						</div>
355→						<div class="form-field">
356→							<label>API Version</label>
357→							<input
358→								type="text"
359→								placeholder="2024-02-15-preview"
360→								.value=${this.azureApiVersion}
361→								@input=${(e: Event) => (this.azureApiVersion = (e.target as HTMLInputElement).value)}
362→							/>
363→						</div>
364→						<div class="form-field">
365→							<label>Deployment Name Map</label>
366→							<input
367→								type="text"
368→								placeholder="gpt-4o=my-gpt4o-deployment"
369→								.value=${this.azureDeploymentNameMap}
370→								@input=${(e: Event) => (this.azureDeploymentNameMap = (e.target as HTMLInputElement).value)}
371→							/>
372→						</div>
373→					</div>
374→				` : null}
375→			</div>
376→		`;
377→	}
378→}
