  1→/**
  2→ * OAuth Connections Panel.
  3→ *
  4→ * User-level component for connecting subscription-based LLM providers
  5→ * (Anthropic Claude Pro, OpenAI Codex, GitHub Copilot, etc.)
  6→ */
  7→
  8→import { apiFetch } from "../shared/api.js";
  9→import { LitElement, html, css } from "lit";
 10→import { customElement, property, state } from "lit/decorators.js";
 11→
 12→interface OAuthConnectionInfo {
 13→	provider: string;
 14→	expiresAt: string;
 15→	expired: boolean;
 16→	createdAt: string;
 17→	updatedAt: string;
 18→}
 19→
 20→const PROVIDER_LABELS: Record<string, string> = {
 21→	anthropic: "Anthropic (Claude Pro/Max)",
 22→	"openai-codex": "OpenAI Codex (ChatGPT Plus/Pro)",
 23→	"github-copilot": "GitHub Copilot",
 24→	"google-gemini-cli": "Google Gemini CLI",
 25→	"google-antigravity": "Google Antigravity",
 26→};
 27→
 28→const PROVIDER_DESCRIPTIONS: Record<string, string> = {
 29→	anthropic: "Connect your Claude Pro or Claude Max subscription",
 30→	"openai-codex": "Connect your ChatGPT Plus or Pro subscription",
 31→	"github-copilot": "Connect your GitHub Copilot subscription (device code flow)",
 32→	"google-gemini-cli": "Connect your Google Gemini CLI account (Google OAuth)",
 33→	"google-antigravity": "Connect your Google Antigravity account (Google OAuth)",
 34→};
 35→
 36→// Providers that are fully supported
 37→const SUPPORTED_PROVIDERS = new Set(["anthropic", "openai-codex", "google-antigravity"]);
 38→
 39→// Providers that need additional implementation (device code flow, etc.)
 40→const COMING_SOON_PROVIDERS = new Set(["github-copilot", "google-gemini-cli"]);
