217→	@state()
218→	private loading = false;
219→
220→	@state()
221→	private connecting: Record<string, boolean> = {};
222→
223→	@state()
224→	private statusMessage = "";
225→
226→	@state()
227→	private statusType: "success" | "error" = "success";
228→
229→	/** Provider currently awaiting a pasted auth code */
230→	@state()
231→	private pendingCodeProvider: string | null = null;
232→
233→	/** The OAuth state token for the pending code exchange */
234→	private pendingState: string | null = null;
235→
236→	/** Reference to the open OAuth popup */
237→	private oauthPopup: Window | null = null;
238→
239→	/** Bound handler for postMessage events from OAuth popup */
240→	private boundMessageHandler: ((e: MessageEvent) => void) | null = null;
241→
242→	/** Whether to show the manual paste fallback hint */
243→	@state()
244→	private showPasteFallback = false;
245→
246→	/** Timer for fallback hint */
247→	private fallbackTimer: ReturnType<typeof setTimeout> | null = null;
248→
249→	override connectedCallback() {
250→		super.connectedCallback();
251→		this.loadConnections();
252→
253→		// Listen for postMessage from OAuth callback popup
254→		this.boundMessageHandler = (e: MessageEvent) => this.handleOAuthMessage(e);
255→		window.addEventListener("message", this.boundMessageHandler);
256→	}
257→
258→	override disconnectedCallback() {
259→		super.disconnectedCallback();
260→		if (this.boundMessageHandler) {
261→			window.removeEventListener("message", this.boundMessageHandler);
262→			this.boundMessageHandler = null;
263→		}
264→		if (this.fallbackTimer) clearTimeout(this.fallbackTimer);
265→	}
266→
267→	/** Handle postMessage from OAuth callback page */
268→	private handleOAuthMessage(e: MessageEvent) {
269→		if (!e.data || e.data.type !== "oauth-callback") return;
270→		// Only accept messages from localhost origins (our OAuth callback servers)
271→		// or same-origin (main server route). The sender uses "*" target because
272→		// the callback page can't know the opener's origin cross-origin, but we
273→		// validate the source here + match the PKCE state below.
274→		if (e.origin && !e.origin.startsWith("http://localhost:") && e.origin !== window.location.origin) {
275→			return;
276→		}
277→		const { code, state } = e.data;
278→		if (!code || !state) return;
279→		// Verify this matches our pending flow
280→		if (state !== this.pendingState) return;
281→
282→		// Auto-complete the flow
283→		this.completeOAuthExchange(code, state);
284→	}
285→
286→	/** Complete token exchange with the server */
287→	private async completeOAuthExchange(code: string, state: string) {
288→		const provider = this.pendingCodeProvider;
289→		if (!provider) return;
290→
291→		// Clear timers
292→		if (this.fallbackTimer) { clearTimeout(this.fallbackTimer); this.fallbackTimer = null; }
293→		this.showPasteFallback = false;
294→
295→		// Close popup if still open
296→		if (this.oauthPopup && !this.oauthPopup.closed) {
297→			this.oauthPopup.close();
298→		}
299→
300→		// Clear pending state
301→		this.pendingCodeProvider = null;
302→		this.pendingState = null;
303→		this.oauthPopup = null;
304→
305→		try {
306→			const callbackResult = await this.fetchApi(`/api/oauth/${provider}/callback`, {
307→				method: "POST",
308→				body: JSON.stringify({ code, state }),
309→			});
310→
311→			if (callbackResult.success) {
312→				this.statusMessage = `Successfully connected ${PROVIDER_LABELS[provider]}`;
313→				this.statusType = "success";
314→				await this.loadConnections();
315→			} else {
316→				this.statusMessage = callbackResult.error || "Failed to complete OAuth flow";
317→				this.statusType = "error";
318→			}
319→		} catch (err) {
320→			console.error("OAuth connection error:", err);
321→			this.statusMessage = "Network error";
322→			this.statusType = "error";
323→		} finally {
324→			this.connecting = { ...this.connecting, [provider]: false };
325→		}
326→	}
327→
328→	private fetchApi = (url: string, options?: RequestInit) => apiFetch(url, options, this.getToken);
329→
330→	private async loadConnections() {
331→		this.loading = true;
332→		try {
333→			const result = await this.fetchApi("/api/oauth");
334→			if (result.success) {
335→				this.connections = result.data.credentials;
336→			}
337→		} catch (err) {
338→			console.error("Failed to load OAuth connections:", err);
339→		} finally {
340→			this.loading = false;
341→		}
342→	}
