344→	private async handleConnect(provider: string) {
345→		this.connecting = { ...this.connecting, [provider]: true };
346→		this.statusMessage = "";
347→
348→		try {
349→			// Start OAuth flow
350→			const startResult = await this.fetchApi(`/api/oauth/${provider}/start`, {
351→				method: "POST",
352→			});
353→
354→			if (!startResult.success) {
355→				this.statusMessage = startResult.error || "Failed to start OAuth flow";
356→				this.statusType = "error";
357→				this.connecting = { ...this.connecting, [provider]: false };
358→				return;
359→			}
360→
361→			const { authUrl, state } = startResult.data;
362→
363→			// Open OAuth URL in popup
364→			const popup = window.open(
365→				authUrl,
366→				"oauth_popup",
367→				"width=600,height=700,left=100,top=100"
368→			);
369→
370→			if (!popup) {
371→				this.statusMessage = "Please allow popups to connect";
372→				this.statusType = "error";
373→				this.connecting = { ...this.connecting, [provider]: false };
374→				return;
375→			}
376→
377→			// Store state and show inline code input
378→			this.oauthPopup = popup;
379→			this.pendingState = state;
380→			this.pendingCodeProvider = provider;
381→			this.showPasteFallback = false;
382→
383→			// For providers using localhost redirects, show fallback paste
384→			// instructions after a delay in case postMessage doesn't work (cloud)
385→			if (this.fallbackTimer) clearTimeout(this.fallbackTimer);
386→			if (provider !== "anthropic") {
387→				this.fallbackTimer = setTimeout(() => {
388→					if (this.pendingCodeProvider) {
389→						this.showPasteFallback = true;
390→					}
391→				}, 5000);
392→			}
393→		} catch (err) {
394→			console.error("OAuth connection error:", err);
395→			this.statusMessage = "Network error";
396→			this.statusType = "error";
397→			this.connecting = { ...this.connecting, [provider]: false };
398→		}
399→	}
