401→	private async handleCodeSubmit() {
402→		const provider = this.pendingCodeProvider;
403→		const state = this.pendingState;
404→		if (!provider || !state) return;
405→
406→		const input = this.shadowRoot?.querySelector<HTMLInputElement>("#oauth-code-input");
407→		const rawValue = input?.value?.trim();
408→		if (!rawValue) return;
409→
410→		// Parse input: accept a full redirect URL, "code#state" format, or bare code
411→		let code: string;
412→		try {
413→			const url = new URL(rawValue);
414→			code = url.searchParams.get("code") || rawValue;
415→		} catch {
416→			code = rawValue.split("#")[0];
417→		}
418→
419→		// Close popup if still open
420→		if (this.oauthPopup && !this.oauthPopup.closed) {
421→			this.oauthPopup.close();
422→		}
423→
424→		// Clear the pending state
425→		this.pendingCodeProvider = null;
426→		this.pendingState = null;
427→		this.oauthPopup = null;
428→
429→		try {
430→			const callbackResult = await this.fetchApi(`/api/oauth/${provider}/callback`, {
431→				method: "POST",
432→				body: JSON.stringify({ code, state }),
433→			});
434→
435→			if (callbackResult.success) {
436→				this.statusMessage = `Successfully connected ${PROVIDER_LABELS[provider]}`;
437→				this.statusType = "success";
438→				await this.loadConnections();
439→			} else {
440→				this.statusMessage = callbackResult.error || "Failed to complete OAuth flow";
441→				this.statusType = "error";
442→			}
443→		} catch (err) {
444→			console.error("OAuth connection error:", err);
445→			this.statusMessage = "Network error";
446→			this.statusType = "error";
447→		} finally {
448→			this.connecting = { ...this.connecting, [provider]: false };
449→		}
450→	}
451→
452→	private handleCodeCancel() {
453→		const provider = this.pendingCodeProvider;
454→		if (this.fallbackTimer) { clearTimeout(this.fallbackTimer); this.fallbackTimer = null; }
455→		this.showPasteFallback = false;
456→		if (this.oauthPopup && !this.oauthPopup.closed) {
457→			this.oauthPopup.close();
458→		}
459→		this.pendingCodeProvider = null;
460→		this.pendingState = null;
461→		this.oauthPopup = null;
462→		if (provider) {
463→			this.connecting = { ...this.connecting, [provider]: false };
464→		}
465→	}
466→
467→	private async handleDisconnect(provider: string) {
468→		if (!confirm(`Disconnect ${PROVIDER_LABELS[provider] || provider}?`)) return;
469→
470→		try {
471→			const result = await this.fetchApi(`/api/oauth/${provider}`, {
472→				method: "DELETE",
473→			});
474→
475→			if (result.success) {
476→				this.statusMessage = `Disconnected ${PROVIDER_LABELS[provider]}`;
477→				this.statusType = "success";
478→				await this.loadConnections();
479→			} else {
480→				this.statusMessage = result.error || "Failed to disconnect";
481→				this.statusType = "error";
482→			}
483→		} catch {
484→			this.statusMessage = "Network error";
485→			this.statusType = "error";
486→		}
487→	}
