  1→/**
  2→ * Provider API key management routes.
  3→ *
  4→ * Admin-only CRUD for team provider keys with envelope encryption.
  5→ * Keys are never returned in API responses — only provider name + status.
  6→ */
  7→
  8→import { Router } from "express";
  9→import type { Request, Response } from "express";
 10→import { getDatabase } from "../db/index.js";
 11→import type { ProviderKeyRow } from "../db/types.js";
 12→import { requireAuth } from "../auth/middleware.js";
 13→import { requireRole } from "../auth/permissions.js";
 14→import type { CryptoService } from "../services/crypto.js";
 15→import { PROVIDER_ENV_MAP } from "../utils/provider-env-map.js";
 16→import { asyncRoute } from "../utils/async-handler.js";
 17→
 18→const VALID_PROVIDERS = new Set(Object.keys(PROVIDER_ENV_MAP));
 19→
 20→export function createProviderKeysRouter(crypto: CryptoService): Router {
 21→	const router = Router();
 22→
 23→	// All routes require admin role
 24→	router.use(requireAuth, requireRole("admin"));
 25→
 26→	// -----------------------------------------------------------------------
 27→	// GET / — List configured providers (never returns actual keys)
 28→	// -----------------------------------------------------------------------
 29→	router.get("/", asyncRoute(async (req, res) => {
 30→		const db = getDatabase();
 31→		const result = await db.query<Pick<ProviderKeyRow, "provider" | "config" | "updated_at">>(
 32→			`SELECT provider, config, updated_at FROM provider_keys WHERE team_id = $1 ORDER BY provider`,
 33→			[req.user!.teamId],
 34→		);
 35→
 36→		const keys = result.rows.map((row) => ({
 37→			provider: row.provider,
 38→			hasKey: true,
 39→			config: row.config,
 40→			updatedAt: row.updated_at,
 41→		}));
 42→
 43→		res.json({ success: true, data: { keys } });
 44→	}));
 45→
 46→	// -----------------------------------------------------------------------
 47→	// POST / — Create or update a provider key
 48→	// -----------------------------------------------------------------------
 49→	router.post("/", asyncRoute(async (req, res) => {
 50→		const { provider, apiKey, config } = req.body;
 51→
 52→		if (!provider || typeof provider !== "string") {
 53→			res.status(400).json({ success: false, error: "provider is required" });
 54→			return;
 55→		}
 56→		if (!apiKey || typeof apiKey !== "string") {
 57→			res.status(400).json({ success: false, error: "apiKey is required" });
 58→			return;
 59→		}
 60→		if (!VALID_PROVIDERS.has(provider)) {
 61→			res.status(400).json({
 62→				success: false,
 63→				error: `Invalid provider. Valid providers: ${Array.from(VALID_PROVIDERS).join(", ")}`,
 64→			});
 65→			return;
 66→		}
 67→
 68→		// Validate config if provided
 69→		let validatedConfig: Record<string, unknown> = {};
 70→		if (config && typeof config === "object" && !Array.isArray(config)) {
 71→			if (provider === "azure-openai") {
 72→				const allowedFields = ["baseUrl", "resourceName", "apiVersion", "deploymentNameMap"];
 73→				for (const [key, value] of Object.entries(config)) {
 74→					if (!allowedFields.includes(key)) continue;
 75→					if (value !== undefined && value !== null && value !== "" && typeof value !== "string") {
 76→						res.status(400).json({ success: false, error: `config.${key} must be a string` });
 77→						return;
 78→					}
 79→					if (value) validatedConfig[key] = value;
 80→				}
 81→				// Validate baseUrl is a valid URL
 82→				if (validatedConfig.baseUrl) {
 83→					try {
 84→						new URL(validatedConfig.baseUrl as string);
 85→					} catch {
 86→						res.status(400).json({ success: false, error: "config.baseUrl must be a valid URL" });
 87→						return;
 88→					}
 89→				}
 90→			}
 91→		}
 92→
 93→		const envelope = crypto.encrypt(apiKey);
 94→		const db = getDatabase();
 95→
 96→		await db.query(
 97→			`INSERT INTO provider_keys (team_id, provider, encrypted_dek, encrypted_key, iv, key_version, config)
 98→			 VALUES ($1, $2, $3, $4, $5, $6, $7)
 99→			 ON CONFLICT (team_id, provider)
100→			 DO UPDATE SET encrypted_dek = $3, encrypted_key = $4, iv = $5,
101→			              key_version = $6, config = $7, updated_at = now()`,
102→			[
103→				req.user!.teamId,
104→				provider,
105→				envelope.encryptedDek,
106→				envelope.encryptedData,
107→				envelope.iv,
108→				envelope.keyVersion,
109→				JSON.stringify(validatedConfig),
110→			],
111→		);
112→
113→		// Audit log
114→		await db.query(
115→			`INSERT INTO provider_key_audit_log (team_id, user_id, provider, action)
116→			 VALUES ($1, $2, $3, $4)`,
117→			[req.user!.teamId, req.user!.userId, provider, "create"],
118→		);
119→
120→		res.status(201).json({ success: true, data: { provider } });
121→	}));
122→
123→	// -----------------------------------------------------------------------
124→	// DELETE /:provider — Delete a provider key
125→	// -----------------------------------------------------------------------
126→	router.delete("/:provider", asyncRoute(async (req, res) => {
127→		const { provider } = req.params;
128→
129→		const db = getDatabase();
130→		const result = await db.query(
131→			`DELETE FROM provider_keys WHERE team_id = $1 AND provider = $2`,
132→			[req.user!.teamId, provider],
133→		);
134→
135→		if (result.rowCount === 0) {
136→			res.status(404).json({ success: false, error: "Provider key not found" });
137→			return;
138→		}
139→
140→		// Audit log
141→		await db.query(
142→			`INSERT INTO provider_key_audit_log (team_id, user_id, provider, action)
143→			 VALUES ($1, $2, $3, $4)`,
144→			[req.user!.teamId, req.user!.userId, provider, "delete"],
145→		);
146→
147→		res.json({ success: true });
148→	}));
149→
150→	return router;
151→}
