 69→/** Discover the Antigravity project ID for the authenticated user. */
 70→async function discoverAntigravityProject(accessToken: string): Promise<string> {
 71→	const DEFAULT_PROJECT_ID = "rising-fact-p41fc";
 72→	const headers = {
 73→		Authorization: `Bearer ${accessToken}`,
 74→		"Content-Type": "application/json",
 75→		"User-Agent": "google-api-nodejs-client/9.15.1",
 76→		"X-Goog-Api-Client": "google-cloud-sdk vscode_cloudshelleditor/0.1",
 77→		"Client-Metadata": JSON.stringify({
 78→			ideType: "IDE_UNSPECIFIED",
 79→			platform: "PLATFORM_UNSPECIFIED",
 80→			pluginType: "GEMINI",
 81→		}),
 82→	};
 83→	const body = JSON.stringify({
 84→		metadata: { ideType: "IDE_UNSPECIFIED", platform: "PLATFORM_UNSPECIFIED", pluginType: "GEMINI" },
 85→	});
 86→
 87→	for (const endpoint of [
 88→		"https://cloudcode-pa.googleapis.com",
 89→		"https://daily-cloudcode-pa.sandbox.googleapis.com",
 90→	]) {
 91→		try {
 92→			const res = await fetch(`${endpoint}/v1internal:loadCodeAssist`, { method: "POST", headers, body });
 93→			if (!res.ok) continue;
 94→			const data = (await res.json()) as {
 95→				cloudaicompanionProject?: string | { id?: string };
 96→			};
 97→			if (typeof data.cloudaicompanionProject === "string" && data.cloudaicompanionProject) {
 98→				return data.cloudaicompanionProject;
 99→			}
100→			if (
101→				data.cloudaicompanionProject &&
102→				typeof data.cloudaicompanionProject === "object" &&
103→				data.cloudaicompanionProject.id
104→			) {
105→				return data.cloudaicompanionProject.id;
106→			}
107→		} catch {
108→			// try next endpoint
109→		}
110→	}
111→	return DEFAULT_PROJECT_ID;
112→}
