114→// Temporary storage for PKCE verifiers (in production, use Redis)
115→const pkceStorage = new Map<string, { verifier: string; userId: string; expiresAt: number }>();
116→
117→// Clean up expired PKCE entries every 10 minutes
118→setInterval(() => {
119→	const now = Date.now();
120→	for (const [key, value] of pkceStorage.entries()) {
121→		if (value.expiresAt < now) {
122→			pkceStorage.delete(key);
123→		}
124→	}
125→}, 10 * 60 * 1000);
