 24→@customElement("provider-key-input")
 25→export class ProviderKeyInput extends LitElement {
 26→	@property() provider = "";
 27→	@state() private keyInput = "";
 28→	@state() private testing = false;
 29→	@state() private failed = false;
 30→	@state() private hasKey = false;
 31→	@state() private inputChanged = false;
 32→
 33→	protected createRenderRoot() {
 34→		return this;
 35→	}
 36→
 37→	override async connectedCallback() {
 38→		super.connectedCallback();
 39→		await this.checkKeyStatus();
 40→	}
 41→
 42→	private async checkKeyStatus() {
 43→		try {
 44→			const key = await getAppStorage().providerKeys.get(this.provider);
 45→			this.hasKey = !!key;
 46→		} catch (error) {
 47→			console.error("Failed to check key status:", error);
 48→		}
 49→	}
 50→
 51→	private async testApiKey(provider: string, apiKey: string): Promise<boolean> {
 52→		try {
 53→			const modelId = TEST_MODELS[provider];
 54→			// Returning true here for Ollama and friends. Can' know which model to use for testing
 55→			if (!modelId) return true;
 56→
 57→			let model = getModel(provider as any, modelId);
 58→			if (!model) return false;
 59→
 60→			// Get proxy URL from settings (if available)
 61→			const proxyEnabled = await getAppStorage().settings.get<boolean>("proxy.enabled");
 62→			const proxyUrl = await getAppStorage().settings.get<string>("proxy.url");
 63→
 64→			// Apply proxy only if this provider/key combination requires it
 65→			model = applyProxyIfNeeded(model, apiKey, proxyEnabled ? proxyUrl || undefined : undefined);
 66→
 67→			const context: Context = {
 68→				messages: [{ role: "user", content: "Reply with: ok", timestamp: Date.now() }],
 69→			};
 70→
 71→			const result = await complete(model, context, {
 72→				apiKey,
 73→				maxTokens: 200,
 74→			} as any);
 75→
 76→			return result.stopReason === "stop";
 77→		} catch (error) {
 78→			console.error(`API key test failed for ${provider}:`, error);
 79→			return false;
 80→		}
 81→	}
 82→
 83→	private async saveKey() {
 84→		if (!this.keyInput) return;
 85→
 86→		this.testing = true;
 87→		this.failed = false;
 88→
 89→		const success = await this.testApiKey(this.provider, this.keyInput);
 90→
 91→		this.testing = false;
 92→
 93→		if (success) {
 94→			try {
 95→				await getAppStorage().providerKeys.set(this.provider, this.keyInput);
 96→				this.hasKey = true;
 97→				this.inputChanged = false;
 98→				this.requestUpdate();
 99→			} catch (error) {
100→				console.error("Failed to save API key:", error);
101→				this.failed = true;
102→				setTimeout(() => {
103→					this.failed = false;
104→					this.requestUpdate();
105→				}, 5000);
106→			}
107→		} else {
108→			this.failed = true;
109→			setTimeout(() => {
110→				this.failed = false;
111→				this.requestUpdate();
112→			}, 5000);
113→		}
114→	}
115→
116→	render() {
117→		return html`
118→			<div class="space-y-3">
119→				<div class="flex items-center gap-2">
120→					<span class="text-sm font-medium capitalize text-foreground">${this.provider}</span>
121→					${
122→						this.testing
123→							? Badge({ children: i18n("Testing..."), variant: "secondary" })
124→							: this.hasKey
125→								? html`<span class="text-green-600 dark:text-green-400">✓</span>`
126→								: ""
127→					}
128→					${this.failed ? Badge({ children: i18n("✗ Invalid"), variant: "destructive" }) : ""}
129→				</div>
130→				<div class="flex items-center gap-2">
131→					${Input({
132→						type: "password",
133→						placeholder: this.hasKey ? "••••••••••••" : i18n("Enter API key"),
134→						value: this.keyInput,
135→						onInput: (e: Event) => {
136→							this.keyInput = (e.target as HTMLInputElement).value;
137→							this.inputChanged = true;
138→							this.requestUpdate();
139→						},
140→						className: "flex-1",
141→					})}
142→					${Button({
143→						onClick: () => this.saveKey(),
144→						variant: "default",
145→						size: "sm",
146→						disabled: !this.keyInput || this.testing || (this.hasKey && !this.inputChanged),
147→						children: i18n("Save"),
148→					})}
149→				</div>
150→			</div>
151→		`;
152→	}
153→}
