 44→	override async firstUpdated(changedProperties: PropertyValues): Promise<void> {
 45→		super.firstUpdated(changedProperties);
 46→		// Wait for dialog to be fully rendered
 47→		await this.updateComplete;
 48→		// Focus the search input when dialog opens
 49→		this.searchInputRef.value?.focus();
 50→
 51→		// Track actual mouse movement
 52→		this.addEventListener("mousemove", (e: MouseEvent) => {
 53→			// Check if mouse actually moved
 54→			if (e.clientX !== this.lastMousePosition.x || e.clientY !== this.lastMousePosition.y) {
 55→				this.lastMousePosition = { x: e.clientX, y: e.clientY };
 56→				// Only switch to mouse mode on actual mouse movement
 57→				if (this.navigationMode === "keyboard") {
 58→					this.navigationMode = "mouse";
 59→					// Update selection to the item under the mouse
 60→					const target = e.target as HTMLElement;
 61→					const modelItem = target.closest("[data-model-item]");
 62→					if (modelItem) {
 63→						const allItems = this.scrollContainerRef.value?.querySelectorAll("[data-model-item]");
 64→						if (allItems) {
 65→							const index = Array.from(allItems).indexOf(modelItem);
 66→							if (index !== -1) {
 67→								this.selectedIndex = index;
 68→							}
 69→						}
 70→					}
 71→				}
 72→			}
 73→		});
 74→
 75→		// Add global keyboard handler for the dialog
 76→		this.addEventListener("keydown", (e: KeyboardEvent) => {
 77→			// Get filtered models to know the bounds
 78→			const filteredModels = this.getFilteredModels();
 79→
 80→			if (e.key === "ArrowDown") {
 81→				e.preventDefault();
 82→				this.navigationMode = "keyboard";
 83→				this.selectedIndex = Math.min(this.selectedIndex + 1, filteredModels.length - 1);
 84→				this.scrollToSelected();
 85→			} else if (e.key === "ArrowUp") {
 86→				e.preventDefault();
 87→				this.navigationMode = "keyboard";
 88→				this.selectedIndex = Math.max(this.selectedIndex - 1, 0);
 89→				this.scrollToSelected();
 90→			} else if (e.key === "Enter") {
 91→				e.preventDefault();
 92→				if (filteredModels[this.selectedIndex]) {
 93→					this.handleSelect(filteredModels[this.selectedIndex].model);
 94→				}
 95→			}
 96→		});
 97→	}
