 99→	private async loadCustomProviders() {
100→		this.customProvidersLoading = true;
101→		const allCustomModels: Model<any>[] = [];
102→
103→		try {
104→			const storage = getAppStorage();
105→			const customProviders = await storage.customProviders.getAll();
106→
107→			// Load models from custom providers
108→			for (const provider of customProviders) {
109→				const isAutoDiscovery: boolean =
110→					provider.type === "ollama" ||
111→					provider.type === "llama.cpp" ||
112→					provider.type === "vllm" ||
113→					provider.type === "lmstudio";
114→
115→				if (isAutoDiscovery) {
116→					try {
117→						const models = await discoverModels(
118→							provider.type as AutoDiscoveryProviderType,
119→							provider.baseUrl,
120→							provider.apiKey,
121→						);
122→
123→						const modelsWithProvider = models.map((model) => ({
124→							...model,
125→							provider: provider.name,
126→						}));
127→
128→						allCustomModels.push(...modelsWithProvider);
129→					} catch (error) {
130→						console.debug(`Failed to load models from ${provider.name}:`, error);
131→					}
132→				} else if (provider.models) {
133→					// Manual provider - models already defined
134→					allCustomModels.push(...provider.models);
135→				}
136→			}
137→		} catch (error) {
138→			console.error("Failed to load custom providers:", error);
139→		} finally {
140→			this.customProviderModels = allCustomModels;
141→			this.customProvidersLoading = false;
142→			this.requestUpdate();
143→		}
144→	}
