const generateTitle = (messages: AgentMessage[]): string => {
	const firstUserMsg = messages.find((m) => m.role === "user" || m.role === "user-with-attachments");
	if (!firstUserMsg || (firstUserMsg.role !== "user" && firstUserMsg.role !== "user-with-attachments")) return "";

	let text = "";
	const content = firstUserMsg.content;

	if (typeof content === "string") {
		text = content;
	} else {
		const textBlocks = content.filter((c: any) => c.type === "text");
		text = textBlocks.map((c: any) => c.text || "").join(" ");
	}

	text = text.trim();
	if (!text) return "";

	const sentenceEnd = text.search(/[.!?]/);
	if (sentenceEnd > 0 && sentenceEnd <= 50) {
		return text.substring(0, sentenceEnd + 1);
	}
	return text.length <= 50 ? text : `${text.substring(0, 47)}...`;
};

const shouldSaveSession = (messages: AgentMessage[]): boolean => {
	const hasUserMsg = messages.some((m: any) => m.role === "user" || m.role === "user-with-attachments");
	const hasAssistantMsg = messages.some((m: any) => m.role === "assistant");
	return hasUserMsg && hasAssistantMsg;
};

const saveSession = async (force = false) => {
	if (!currentSessionId || !remoteAgent || !storage) return;
	if (!force && !currentTitle) return;

	const state = remoteAgent.state;
	if (!force && !shouldSaveSession(state.messages)) return;

	try {
		// Capture binary artifact content (PPTX slides, etc.) for persistence
		const artifactsCache: Record<string, string> = {};
		const panel = chatPanel?.artifactsPanel;
		if (panel) {
			for (const [filename, artifact] of panel.artifacts) {
				const ext = filename.split(".").pop()?.toLowerCase();
				if (ext && BINARY_EXTENSIONS.has(ext) && artifact.content) {
					artifactsCache[filename] = artifact.content;
				}
			}
		}

		const sessionData = {
			id: currentSessionId,
			title: currentTitle,
			model: state.model!,
			modelId: state.model?.id || null,
			provider: state.model?.provider || null,
			thinkingLevel: state.thinkingLevel,
			messages: state.messages,
			agentProfileId: currentAgentProfileId || null,
			createdAt: new Date().toISOString(),
			lastModified: new Date().toISOString(),
			...(Object.keys(artifactsCache).length > 0 ? { artifactsCache } : {}),
		};

		const metadata = {
			id: currentSessionId,
			title: currentTitle,
			createdAt: sessionData.createdAt,
			lastModified: sessionData.lastModified,
			messageCount: state.messages.length,
			usage: {
				input: 0,
				output: 0,
				cacheRead: 0,
				cacheWrite: 0,
				totalTokens: 0,
				cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 },
			},
			modelId: state.model?.id || null,
			thinkingLevel: state.thinkingLevel,
			preview: generateTitle(state.messages),
			agentProfileId: currentAgentProfileId || null,
		};

		await storage.sessions.save(sessionData, metadata);
		// Refresh sidebar after saving
		loadSidebarSessions();
	} catch (err) {
		console.error("Failed to save session:", err);
	}
};

const loadSession = async (sessionId: string): Promise<boolean> => {
	if (!storage) return false;

	// Bump generation so any in-flight switch from a previous click is discarded
	const gen = ++sessionSwitchGen;

	// If the session was running in the background, invalidate the cache
	// so we fetch fresh data (including messages generated while away)
	const bgStatus = sessionStatusMap.get(sessionId);
	if (bgStatus === "generating" || bgStatus === "idle") {
		(storage.backend as any).invalidate?.("sessions", sessionId);
	}

	const sessionData = await storage.sessions.get(sessionId);
	if (gen !== sessionSwitchGen) return false; // superseded by a newer switch
	if (!sessionData) {
		console.error("Session not found:", sessionId);
		return false;
	}

	const metadata = await storage.sessions.getMetadata(sessionId);
	if (gen !== sessionSwitchGen) return false; // superseded by a newer switch

	// Store messages and artifact cache to restore after WebSocket reconnects
	pendingSessionMessages = sessionData.messages;
	pendingArtifactsCache = (sessionData as any).artifactsCache ?? null;

	// Disconnect old WebSocket cleanly — this flushes any pending session save
	disconnectWebSocket();

	// Update state for the new session
	currentSessionId = sessionId;
	currentTitle = metadata?.title || "";
	currentAgentProfileId = (metadata as any)?.agentProfileId || undefined;
	currentModelId = undefined;
	currentProvider = undefined;
	chatPanel?.artifactsPanel?.clear();
	fetchedFileRefs.clear();
	saveSessionState();

	// Reconnect — the URL will include the sessionId + agentProfileId
	connectWebSocket();
	renderApp();
	return true;
};

const abortSession = async (sessionId: string) => {
	try {
		await fetch("/api/sessions/" + sessionId + "/abort", {
			method: "POST",
			headers: { Authorization: "Bearer " + authClient.token },
		});
	} catch (err) {
